-- معايير التصنيف المتدرّجة: قطاع ← صناعة ← نشاط، بدورة مسودة ← مراجعة ← اعتماد.
-- النسخة العاملة قابلة للتعديل، واللقطة المنشورة لا تتغيّر إلا بالاعتماد؛ فلا يرى العموم إلا المعتمد.
CREATE TABLE public.classification_standards (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  level text NOT NULL CHECK (level IN ('sector', 'industry', 'activity')),
  node_key text NOT NULL CHECK (char_length(btrim(node_key)) BETWEEN 1 AND 200),
  title_ar text NOT NULL CHECK (char_length(btrim(title_ar)) BETWEEN 3 AND 200),
  title_en text CHECK (title_en IS NULL OR char_length(title_en) <= 200),
  summary_ar text NOT NULL CHECK (char_length(btrim(summary_ar)) BETWEEN 10 AND 2000),
  summary_en text CHECK (summary_en IS NULL OR char_length(summary_en) <= 2000),
  requirements jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(requirements) = 'array'),
  sources jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(sources) = 'array'),
  status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'pending_review', 'approved', 'rejected')),
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  review_note text CHECK (review_note IS NULL OR char_length(review_note) <= 1000),
  published_snapshot jsonb,
  published_version integer,
  published_at timestamptz,
  created_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  updated_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  reviewed_by uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  reviewed_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (level, node_key)
);
GRANT SELECT ON public.classification_standards TO authenticated;
GRANT ALL ON public.classification_standards TO service_role;
ALTER TABLE public.classification_standards ENABLE ROW LEVEL SECURITY;
-- القراءة المباشرة للمراجعين والمديرين فقط؛ والعموم يرون اللقطة المنشورة عبر دالة الخادم.
CREATE POLICY "Reviewers can read classification standards" ON public.classification_standards FOR SELECT TO authenticated
  USING (private.has_role(auth.uid(), 'admin') OR private.has_role(auth.uid(), 'reviewer'));
CREATE TRIGGER classification_standards_updated_at BEFORE UPDATE ON public.classification_standards FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE INDEX classification_standards_status_idx ON public.classification_standards (status);

CREATE TABLE public.classification_standard_revisions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  standard_id uuid NOT NULL REFERENCES public.classification_standards(id) ON DELETE CASCADE,
  action text NOT NULL CHECK (action IN ('create', 'update', 'submit', 'approve', 'reject')),
  snapshot jsonb NOT NULL,
  actor_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  note text CHECK (note IS NULL OR char_length(note) <= 1000),
  created_at timestamptz NOT NULL DEFAULT now()
);
GRANT SELECT ON public.classification_standard_revisions TO authenticated;
GRANT ALL ON public.classification_standard_revisions TO service_role;
ALTER TABLE public.classification_standard_revisions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Reviewers can read classification standard revisions" ON public.classification_standard_revisions FOR SELECT TO authenticated
  USING (private.has_role(auth.uid(), 'admin') OR private.has_role(auth.uid(), 'reviewer'));
CREATE INDEX classification_standard_revisions_standard_idx ON public.classification_standard_revisions (standard_id, created_at DESC);

-- مسودات معايير القطاعات الخمسة: غير منشورة، وتنتظر مراجعة الهيئة الشرعية.
INSERT INTO public.classification_standards (level, node_key, title_ar, title_en, summary_ar, summary_en, requirements, sources, status, review_note) VALUES
  ('sector', $v$p$v$, $v$المعيار الشرعي للقطاع الأولي: استخلاص الموارد الطبيعية وإنتاجها$v$, $v$Shariah standard for the primary sector: extraction and production of natural resources$v$, $v$يضبط هذا المعيار أنشطة الزراعة والثروة الحيوانية والسمكية والغابات والتعدين واستخراج الطاقة: مشروعية الحيازة والانتفاع، وعقود الشراكة الزراعية، وبيوع المحاصيل، وأحكام الحيوان، ووعاء الزكاة، وحفظ الموارد من الإفساد. ويسري على كل صناعات القطاع وأنشطته ما لم يرد في معيار الصناعة أو النشاط حكمٌ أخص.$v$, $v$Governs agriculture, livestock, fisheries, forestry, mining and energy extraction: lawful tenure and use, agricultural partnership contracts, crop sales, animal rulings, the zakat base, and protecting resources from harm. It applies to every industry and activity in the sector unless a more specific industry or activity standard provides otherwise.$v$, $v$[{"kind": "mandatory", "ar": "مشروعية الحيازة والانتفاع: أن يقوم النشاط على ملكٍ صحيح أو إذنٍ معتبر (امتياز، أو إقطاع، أو إجارة أرض، أو ترخيص صيد أو تعدين)، دون تعدٍّ على الملك العام أو الخاص أو المراعي والمياه المشتركة.", "en": "Lawful tenure and use: the activity must rest on valid ownership or a recognised permission (concession, land grant, land lease, fishing or mining licence), without encroaching on public or private property or shared pasture and water.", "ref": "أحكام إحياء الموات والإقطاع؛ حديث «الناس شركاء في ثلاث»"}, {"kind": "condition", "ar": "عقود المزارعة والمساقاة والمغارسة: تُحدَّد حصة كل طرف جزءًا شائعًا من الناتج لا مقدارًا مقطوعًا، ويُبيَّن محل العقد والعمل والمدة وعلى من البذر والنفقات.", "en": "Muzara'ah, musaqah and mugharasah contracts: each party's share must be a common proportion of the output, not a fixed quantity; the subject, work, term and who bears seed and costs must be stated.", "ref": "معاملة النبي ﷺ أهل خيبر؛ قول جمهور الفقهاء بالجواز"}, {"kind": "condition", "ar": "السَّلَم في المحاصيل والمنتجات: بيان الجنس والنوع والصفة والمقدار والأجل ومكان التسليم، وتسليم رأس المال في مجلس العقد، وألا يُعيَّن المُسلَم فيه من أرضٍ أو بستانٍ بعينه.", "en": "Salam in crops and produce: specify genus, type, quality, quantity, term and place of delivery; pay the capital at the contract session; and do not tie the subject to a specific plot or orchard.", "ref": "AAOIFI المعيار الشرعي 10 (السلم والسلم الموازي)"}, {"kind": "prohibition", "ar": "بيع الثمار قبل بُدُوّ صلاحها بشرط التبقية، وبيع ما لا يُقدَر على تسليمه أو ما فيه غررٌ فاحش كالسمك في الماء قبل صيده.", "en": "Selling fruit before it ripens on condition that it stays on the tree, or selling what cannot be delivered or involves gross gharar, such as fish in the water before it is caught.", "ref": "النهي عن بيع الثمار حتى يبدو صلاحها؛ النهي عن بيع الغرر"}, {"kind": "mandatory", "ar": "في الإنتاج الحيواني: الذكاة الشرعية لما يُذبح، وطِيب العلف، ومنع تغذية الحيوان بالنجاسات حتى يصير جلّالًا ما لم يُحبس ويُطهَّر وفق المعتمد.", "en": "In livestock production: Shariah-compliant slaughter, wholesome feed, and no feeding on impurities that renders an animal jallalah unless it is confined and cleansed as approved.", "ref": "OIC/SMIIC 1 (متطلبات الغذاء الحلال)؛ أحكام الجلّالة"}, {"kind": "mandatory", "ar": "الإحسان إلى الحيوان: منع التعذيب، والتحميل فوق الطاقة، والحبس المؤذي، والتجويع، في التربية والنقل والذبح.", "en": "Kindness to animals: no torture, overloading, harmful confinement or starvation in rearing, transport or slaughter.", "ref": "حديث «إن الله كتب الإحسان على كل شيء»"}, {"kind": "mandatory", "ar": "حفظ الموارد ومنع الإفساد: لا استنزاف جائر للمياه والتربة والمخزون السمكي والغابات، ولا تلويث يضرّ بالجماعة أو الأجيال اللاحقة.", "en": "Protecting resources and preventing harm: no depletion of water, soil, fish stocks or forests, and no pollution that harms the community or later generations.", "ref": "قاعدة «لا ضرر ولا ضرار»؛ مقصدا حفظ النفس والمال"}, {"kind": "prohibition", "ar": "إنتاج ما يُتّخذ للمحرّم أو بيعه لمن يُعلم أو يغلب على الظن أنه يتخذه له، كبيع العنب لمصانع الخمر. وتُحال زراعة التبغ إلى الهيئة الشرعية لتفاوت الاجتهاد المعاصر فيها.", "en": "Producing what is used for the prohibited, or selling it to someone known or likely to use it so, such as grapes for wineries. Tobacco cultivation is referred to the Shariah board given differing contemporary opinions.", "ref": "قاعدة سدّ الذرائع؛ النهي عن الإعانة على الإثم"}, {"kind": "condition", "ar": "وعاء الزكاة: الإفصاح عن الأصول الزكوية للنشاط، ومنها الزروع والثمار عند الحصاد (العشر فيما سُقي بلا مؤونة ونصفه فيما سُقي بمؤونة)، وبهيمة الأنعام السائمة، والمعادن والركاز، وفق منهجية تعتمدها الهيئة.", "en": "Zakat base: disclose the zakatable assets of the activity, including crops at harvest (a tenth when rain-fed, a twentieth when irrigated at cost), grazing livestock, and minerals and buried treasure, following a methodology approved by the board.", "ref": "AAOIFI المعيار الشرعي 35 (الزكاة)"}, {"kind": "condition", "ar": "التمويل: يُقدَّم تمويل النشاط بصيغ مشروعة كالسلم والمزارعة والإجارة والمرابحة، ويخضع أي تمويل ربوي لحدود الفرز المالي في بوابة الأهلية.", "en": "Financing: use lawful structures such as salam, muzara'ah, ijarah and murabahah; any interest-bearing financing is subject to the eligibility gate's financial screens.", "ref": "AAOIFI المعيار الشرعي 21 (حدود الفرز)"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 10 (السلم)", "AAOIFI المعيار الشرعي 21 (الأوراق المالية)", "AAOIFI المعيار الشرعي 35 (الزكاة)", "OIC/SMIIC 1 (الغذاء الحلال)"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('sector', $v$s$v$, $v$المعيار الشرعي للقطاع الثانوي: التصنيع والتحويل والبناء$v$, $v$Shariah standard for the secondary sector: manufacturing, processing and construction$v$, $v$يضبط هذا المعيار أنشطة التصنيع والتحويل والبناء والمرافق: حِلّ المُدخلات والمُخرجات، وعقود الاستصناع والمقاولات، والجودة والوفاء بالمواصفات، وحقوق العاملين، والسلامة والبيئة، وتمويل الأصول الثابتة. ويسري على كل صناعات القطاع وأنشطته ما لم يرد حكمٌ أخص.$v$, $v$Governs manufacturing, processing, construction and utilities: lawful inputs and outputs, istisna' and contracting, quality and specification compliance, workers' rights, safety and environment, and fixed-asset financing. It applies to every industry and activity in the sector unless a more specific ruling applies.$v$, $v$[{"kind": "prohibition", "ar": "تصنيع المحرّمات لذاتها أو ما يغلب استعماله فيها: الخمور والمسكرات، ولحم الخنزير ومشتقاته، وأدوات القمار، والمواد الإباحية، وما لا منفعة مباحة فيه.", "en": "Manufacturing what is prohibited in itself or mainly used for it: alcohol and intoxicants, pork and its derivatives, gambling equipment, pornographic material, and anything without a lawful use.", "ref": "النهي عن الإعانة على الإثم والعدوان"}, {"kind": "mandatory", "ar": "حِلّ المُدخلات: التحقق من حِلّ المكوّنات والمضافات والمساعدات التصنيعية (كالجيلاتين والإنزيمات والكحول)، وتوثيق سلسلة الإمداد. ويُعمَل بالاستحالة والاستهلاك وفق ما تعتمده الهيئة.", "en": "Lawful inputs: verify ingredients, additives and processing aids (such as gelatin, enzymes and alcohol) and document the supply chain. Transformation (istihalah) and dilution (istihlak) apply as approved by the board.", "ref": "OIC/SMIIC 1 (الغذاء الحلال)"}, {"kind": "condition", "ar": "الاستصناع: وصفٌ منضبط للمصنوع يرفع الجهالة، وتحديد الثمن وأجل التسليم. ويجوز تأجيل الثمن وتقسيطه، ويجوز الشرط الجزائي على التأخير في التسليم لا على تأخر سداد الديون.", "en": "Istisna': a precise description of the item that removes uncertainty, and a fixed price and delivery date. Price may be deferred or paid in instalments; a penalty clause may apply to late delivery but not to late payment of debts.", "ref": "AAOIFI المعيار الشرعي 11 (الاستصناع والاستصناع الموازي)"}, {"kind": "condition", "ar": "عقود البناء والمقاولات: تحديد العمل والمواصفات والمدة والثمن، ويضمن المقاول ما تلف بتعدّيه أو تقصيره، ولا يضمن ما تلف بغير تعدٍّ.", "en": "Construction contracts: define the work, specifications, term and price; the contractor is liable for damage caused by transgression or negligence, not otherwise.", "ref": "أحكام الأجير المشترك والضمان"}, {"kind": "mandatory", "ar": "الوفاء بالمواصفات والجودة، وبيان العيوب، ومنع الغش والتدليس في المكوّنات والأوزان وبلد المنشأ.", "en": "Meet specifications and quality, disclose defects, and avoid fraud or misrepresentation in ingredients, weights and country of origin.", "ref": "حديث «من غشّنا فليس منّا»"}, {"kind": "mandatory", "ar": "حقوق العاملين: أجرٌ معلوم عادل يُدفع في وقته، وساعات عمل لا تُرهق، وسلامة مهنية، ومنع السُّخرة وعمل الأطفال الضار.", "en": "Workers' rights: a known, fair wage paid on time, reasonable hours, occupational safety, and no forced labour or harmful child labour.", "ref": "حديث «أعطوا الأجير أجره قبل أن يجفّ عرقه»؛ أحكام إجارة الأشخاص"}, {"kind": "mandatory", "ar": "السلامة والبيئة: إدارة الانبعاثات والنفايات والمواد الخطرة بما يمنع الضرر بالعاملين والجوار والبيئة.", "en": "Safety and environment: manage emissions, waste and hazardous materials so as to prevent harm to workers, neighbours and the environment.", "ref": "قاعدة «لا ضرر ولا ضرار»"}, {"kind": "prohibition", "ar": "الاحتكار والتواطؤ على الأسعار أو تقاسم الأسواق بما يضرّ بالناس.", "en": "Hoarding, price collusion or market sharing that harms people.", "ref": "حديث «لا يحتكر إلا خاطئ»"}, {"kind": "condition", "ar": "تمويل الأصول الثابتة: يُقدَّم تمويل المصانع والمعدات بصيغ مشروعة كالإجارة المنتهية بالتمليك والمرابحة والمشاركة المتناقصة، ويخضع أي تمويل ربوي لحدود الفرز المالي في بوابة الأهلية.", "en": "Fixed-asset financing: finance plants and equipment through lawful structures such as ijarah ending in ownership, murabahah and diminishing musharakah; any interest-bearing financing is subject to the eligibility gate's financial screens.", "ref": "AAOIFI المعايير الشرعية 8 (المرابحة) و9 (الإجارة) و12 (الشركة)"}, {"kind": "recommended", "ar": "الحصول على شهادة حلال معتمدة للمنتجات الغذائية والدوائية ومستحضرات التجميل من جهة اعتماد معترف بها.", "en": "Obtain accredited halal certification for food, pharmaceutical and cosmetic products from a recognised certification body.", "ref": "OIC/SMIIC 2 و3 (متطلبات جهات الشهادة والاعتماد)"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 8 (المرابحة)", "AAOIFI المعيار الشرعي 9 (الإجارة)", "AAOIFI المعيار الشرعي 11 (الاستصناع)", "AAOIFI المعيار الشرعي 12 (الشركة)", "OIC/SMIIC 1 و2 و3"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('sector', $v$t$v$, $v$المعيار الشرعي للقطاع الثالثي: الخدمات والتجارة$v$, $v$Shariah standard for the tertiary sector: services and trade$v$, $v$يضبط هذا المعيار أنشطة التجارة والنقل والخدمات المالية والصحية والسياحية والشخصية والإدارية: صحة عقود البيع والإجارة، واجتناب الربا والغرر والغش، وأحكام الصرف والتأمين، وأخلاقيات التسويق، وحماية بيانات العملاء، ومعالجة الدخل المختلط. ويسري على كل صناعات القطاع وأنشطته ما لم يرد حكمٌ أخص.$v$, $v$Governs trade, transport, financial, health, tourism, personal and administrative services: valid sale and lease contracts, avoiding riba, gharar and fraud, currency exchange and insurance rulings, marketing ethics, customer data protection, and handling mixed income. It applies to every industry and activity in the sector unless a more specific ruling applies.$v$, $v$[{"kind": "prohibition", "ar": "تقديم خدمة محرّمة لذاتها أو الإعانة عليها أساسًا: خدمات القمار والمراهنات، وتقديم الخمور، والدعارة، والإقراض بفائدة.", "en": "Providing a service prohibited in itself or mainly supporting it: gambling and betting, serving alcohol, prostitution, and interest-based lending.", "ref": "النهي عن الإعانة على الإثم والعدوان"}, {"kind": "mandatory", "ar": "البيع والتجارة: ألا يبيع التاجر ما لا يملك، وأن يقبض ما يُشترط قبضه قبل بيعه، مع إعمال خيارات العيب والشرط.", "en": "Sales and trade: do not sell what you do not own, take possession where required before resale, and honour the options for defects and conditions.", "ref": "حديث «لا تبع ما ليس عندك»"}, {"kind": "prohibition", "ar": "بيع العِينة، والنجش، والغش، والتدليس، والاحتكار، وتلقّي الركبان على وجه الإضرار.", "en": "'Inah sales, bid rigging (najsh), fraud, misrepresentation, hoarding, and intercepting sellers before they reach the market to their detriment.", "ref": "النهي عن النجش والغش والاحتكار"}, {"kind": "mandatory", "ar": "الصرف ومبادلة الأثمان: التقابض في المجلس عند مبادلة العملات، ومنع الزيادة على الدين مقابل تأجيله. وما يُفرض من غرامات تأخير على المماطل يُصرف في وجوه الخير ولا يدخل في إيراد المنشأة.", "en": "Currency exchange: exchange currencies hand to hand at the contract session, and never add to a debt in return for deferral. Late-payment charges on a defaulting debtor go to charity and are not income.", "ref": "AAOIFI المعيار الشرعي 1 (المتاجرة في العملات)"}, {"kind": "condition", "ar": "إجارة المنافع والخدمات: بيان المنفعة والمدة والأجرة بيانًا نافيًا للجهالة، وتحمّل المؤجر ما يلزم لبقاء المنفعة.", "en": "Leasing of usufruct and services: specify the benefit, term and fee so as to remove uncertainty; the lessor bears what is needed to keep the benefit available.", "ref": "AAOIFI المعيار الشرعي 9 (الإجارة)"}, {"kind": "condition", "ar": "التأمين: يُقدَّم التأمين التكافلي على التأمين التجاري حيث يتاح، ويُفصَح عمّا يُلجأ إليه للحاجة أو الإلزام النظامي.", "en": "Insurance: prefer takaful to conventional insurance where available, and disclose any conventional cover taken out of need or legal obligation.", "ref": "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)"}, {"kind": "condition", "ar": "الوساطة والعمولات: أن تكون العمولة معلومة، وألا تُربط أجرة الخدمة بمقدار قرضٍ أو أجله على نحوٍ يكون ذريعة إلى الربا.", "en": "Brokerage and commissions: the fee must be known, and service fees must not be tied to a loan's amount or term in a way that becomes a route to riba.", "ref": "قاعدة «كل قرض جرّ نفعًا فهو ربا»"}, {"kind": "mandatory", "ar": "أخلاقيات التسويق: الصدق في الوصف والسعر، ومنع التغرير والإعلانات المخالفة للآداب العامة أو المستهدِفة للقُصّر بما يضرّهم.", "en": "Marketing ethics: truthful descriptions and prices; no deception, and no advertising that breaches public morals or harmfully targets minors.", "ref": "حديث «البيّعان بالخيار… فإن صدقا وبيّنا بورك لهما»"}, {"kind": "mandatory", "ar": "حماية بيانات العملاء وخصوصيتهم: جمعها بإذن ولغرض مشروع، وعدم بيعها أو الانتفاع بها بغير رضا أصحابها.", "en": "Protect customer data and privacy: collect it with consent for a lawful purpose, and do not sell or exploit it without the owners' approval.", "ref": "أحكام الأمانة وحرمة التجسّس"}, {"kind": "condition", "ar": "الأنشطة المختلطة: فصل الإيراد غير المباح في الحسابات وتطهيره، مع الالتزام بحدود الفرز المالي في بوابة الأهلية.", "en": "Mixed activities: separate non-permissible income in the accounts and purify it, within the eligibility gate's financial screens.", "ref": "AAOIFI المعيار الشرعي 21 (حدود الفرز والتطهير)"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 1 (المتاجرة في العملات)", "AAOIFI المعيار الشرعي 9 (الإجارة)", "AAOIFI المعيار الشرعي 21 (الأوراق المالية)", "AAOIFI المعيار الشرعي 26 (التأمين الإسلامي)"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('sector', $v$q$v$, $v$المعيار الشرعي للقطاع الرباعي: المعرفة والتقنية والبحث$v$, $v$Shariah standard for the quaternary sector: knowledge, technology and research$v$, $v$يضبط هذا المعيار أنشطة التقنية والاقتصاد الرقمي والبحث والتعليم المتقدم والخدمات المهنية المعرفية: الحقوق المعنوية، وعقود البرمجيات والتراخيص، والبيانات والخصوصية، والأصول الرقمية، والذكاء الاصطناعي، وأخلاقيات البحث، وتمويل الشركات الناشئة. ويسري على كل صناعات القطاع وأنشطته ما لم يرد حكمٌ أخص.$v$, $v$Governs technology, the digital economy, research, advanced education and knowledge-based professional services: intellectual property, software and licensing contracts, data and privacy, digital assets, artificial intelligence, research ethics, and start-up financing. It applies to every industry and activity in the sector unless a more specific ruling applies.$v$, $v$[{"kind": "mandatory", "ar": "الحقوق المعنوية (الملكية الفكرية وبراءات الاختراع والعلامات والأسماء التجارية) حقوقٌ مالية معتبرة شرعًا: يُمنع الاعتداء عليها أو الانتفاع بها بغير إذن أصحابها.", "en": "Intellectual property (copyright, patents, trademarks and trade names) is a recognised financial right: it must not be infringed or used without the owner's permission.", "ref": "قرار مجمع الفقه الإسلامي الدولي بشأن الحقوق المعنوية"}, {"kind": "condition", "ar": "عقود البرمجيات والتراخيص والاشتراكات: وصف منضبط للخدمة ومستوى أدائها ومدتها وأجرتها. وتُكيَّف البرمجيات المخصّصة استصناعًا، والاشتراكات إجارةَ منافع.", "en": "Software, licensing and subscription contracts: a precise description of the service, its performance level, term and fee. Custom software is treated as istisna', subscriptions as a lease of usufruct.", "ref": "AAOIFI المعياران الشرعيان 9 (الإجارة) و11 (الاستصناع)"}, {"kind": "prohibition", "ar": "تطوير منصات القمار والمراهنات أو تشغيلها، وكذلك المحتوى الإباحي، وتطبيقات الإقراض بفائدة، وألعاب الحظ المدفوعة المبنية على الغرر.", "en": "Building or operating gambling and betting platforms, pornographic content, interest-based lending apps, or paid games of chance built on gharar.", "ref": "تحريم الميسر والربا"}, {"kind": "mandatory", "ar": "البيانات والخصوصية: جمع البيانات بإذنٍ ولغرضٍ مشروع، وعدم بيعها أو توظيفها بما يخالف الأمانة، والإفصاح عن سياسات استخدامها.", "en": "Data and privacy: collect data with consent for a lawful purpose, do not sell or use it in breach of trust, and disclose how it is used.", "ref": "أحكام الأمانة وحرمة التجسّس"}, {"kind": "condition", "ar": "الأصول الرقمية والعملات المشفّرة في وضع «قيد الدراسة / إحالة» ما لم تصدر الهيئة قرارًا فيها. ويُمنع التداول بالهامش القائم على القروض الربوية والمشتقات القائمة على الرهان.", "en": "Digital assets and cryptocurrencies stay \"under study / referral\" until the board rules. Margin trading funded by interest-bearing loans and betting-based derivatives are not permitted.", "ref": "مرجعية المعيار: قرار مجمع الفقه 237 بالتوقف وطلب مزيد من الدراسة"}, {"kind": "condition", "ar": "الذكاء الاصطناعي والخوارزميات: الشفافية وعدم التضليل، ومنع التحيّز الضار، ومسؤولية المشغّل عمّا تُحدثه الأنظمة من ضرر، وعدم نسبة الفتوى أو الحكم الشرعي إلى النظام الآلي.", "en": "Artificial intelligence and algorithms: transparency and no deception, preventing harmful bias, operator liability for harm caused by the system, and never attributing a fatwa or Shariah ruling to an automated system.", "ref": "قاعدة «لا ضرر ولا ضرار»؛ مبدأ المساءلة"}, {"kind": "condition", "ar": "البحث العلمي: الالتزام بأخلاقيات البحث وحفظ النفس والكرامة الإنسانية، وأخذ الموافقة المستنيرة، ومنع التجارب المحرّمة كالاستنساخ البشري.", "en": "Scientific research: follow research ethics, protect life and human dignity, obtain informed consent, and prohibit forbidden experiments such as human cloning.", "ref": "مقصدا حفظ النفس والنسل"}, {"kind": "condition", "ar": "الإيرادات الإعلانية: التحقق من مشروعية المعلَن عنه، وتطهير ما يرد من إعلانات محرّمة إن تعذّر منعها ابتداءً.", "en": "Advertising revenue: verify that what is advertised is lawful, and purify income from prohibited adverts that could not be blocked in advance.", "ref": "AAOIFI المعيار الشرعي 21 (التطهير)"}, {"kind": "condition", "ar": "تمويل الشركات الناشئة: صيغ المشاركة والمضاربة. ويُتجنّب الأسهم الممتازة ذات العائد المضمون، والقروض القابلة للتحويل بفائدة.", "en": "Start-up financing: musharakah and mudarabah structures; avoid preferred shares with guaranteed returns and interest-bearing convertible notes.", "ref": "AAOIFI المعياران الشرعيان 12 (الشركة) و13 (المضاربة)"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 9 (الإجارة)", "AAOIFI المعيار الشرعي 11 (الاستصناع)", "AAOIFI المعيار الشرعي 12 (الشركة)", "AAOIFI المعيار الشرعي 13 (المضاربة)", "AAOIFI المعيار الشرعي 21 (الأوراق المالية)", "قرارات مجمع الفقه الإسلامي الدولي"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$),
  ('sector', $v$n$v$, $v$المعيار الشرعي للقطاع الخماسي: القيادة وصنع السياسات والتوجيه$v$, $v$Shariah standard for the quinary sector: leadership, policy-making and direction$v$, $v$يضبط هذا المعيار أنشطة القيادة العليا وصنع السياسات والجهات المرجعية وإدارة المال العام والأوقاف الكبرى: العدل وأداء الأمانة، والشورى والحوكمة، ومنع الرشوة وتعارض المصالح، وتوجيه السياسات الاقتصادية نحو المقاصد، وحفظ المال العام والأوقاف، والرقابة الشرعية المستقلة. ويسري على كل صناعات القطاع وأنشطته ما لم يرد حكمٌ أخص.$v$, $v$Governs top leadership, policy-making, reference bodies and the management of public funds and major endowments: justice and trust, consultation and governance, preventing bribery and conflicts of interest, steering economic policy toward the objectives of Shariah, safeguarding public funds and awqaf, and independent Shariah oversight. It applies to every industry and activity in the sector unless a more specific ruling applies.$v$, $v$[{"kind": "mandatory", "ar": "العدل وأداء الأمانة في الولايات العامة والخاصة، وتقديم الأكفأ الأمين في المسؤوليات.", "en": "Justice and faithful discharge of trust in public and private office, appointing the most competent and trustworthy.", "ref": "قوله تعالى: ﴿إن الله يأمركم أن تؤدوا الأمانات إلى أهلها﴾"}, {"kind": "mandatory", "ar": "الشورى والحوكمة: فصل الصلاحيات، وتوثيق القرارات، والإفصاح الدوري عن الأداء والمخاطر.", "en": "Consultation and governance: separation of powers, documented decisions, and regular disclosure of performance and risks.", "ref": "قوله تعالى: ﴿وأمرهم شورى بينهم﴾"}, {"kind": "prohibition", "ar": "الرشوة، والمحاباة، واستغلال النفوذ، وقبول الهدايا بسبب الولاية.", "en": "Bribery, favouritism, abuse of influence, and accepting gifts because of one's office.", "ref": "حديث «لعن رسول الله ﷺ الراشي والمرتشي»؛ حديث ابن اللُّتبيّة"}, {"kind": "mandatory", "ar": "منع تعارض المصالح: الإفصاح عن المصالح الشخصية، وتنحّي صاحب المصلحة عن القرار المتصل بها.", "en": "Preventing conflicts of interest: disclose personal interests, and recuse the interested party from related decisions.", "ref": "قاعدة سدّ الذرائع"}, {"kind": "condition", "ar": "السياسات الاقتصادية والتنظيمية: ألا تُلزِم بالتعامل بالربا أو الغرر أو تشجّع عليه حيث توجد بدائل مشروعة، وأن تُبنى على المصلحة المعتبرة ومقاصد الشريعة.", "en": "Economic and regulatory policy: do not mandate or encourage dealing in riba or gharar where lawful alternatives exist, and base policy on recognised public interest and the objectives of Shariah.", "ref": "قاعدة «تصرّف الإمام على الرعية منوطٌ بالمصلحة»"}, {"kind": "mandatory", "ar": "المال العام والأوقاف: حفظ الأصل وتنميته بالصيغ المشروعة، وصرف الريع وفق شرط الواقف أو المصلحة العامة، مع المحاسبة والتدقيق المستقل.", "en": "Public funds and awqaf: preserve and grow the principal through lawful structures, spend the income per the endower's conditions or the public interest, with independent accounting and audit.", "ref": "AAOIFI المعيار الشرعي 33 (الوقف)؛ قاعدة «شرط الواقف كنصّ الشارع»"}, {"kind": "mandatory", "ar": "الرقابة الشرعية المستقلة للجهات المرجعية، وإعلان مناهج الترجيح والاجتهاد، ونشر القرارات بأرقامها وأدلتها.", "en": "Independent Shariah oversight of reference bodies, with published methods of preference and ijtihad, and decisions published with their numbers and evidence.", "ref": "مبدأ الشفافية في المعيار"}, {"kind": "recommended", "ar": "الاستشارات الاستراتيجية: الامتناع عن تقديم المشورة لمشروعاتٍ محرّمة، وتقديم البدائل المشروعة عند الإمكان.", "en": "Strategic advisory: decline to advise on prohibited projects, and propose lawful alternatives where possible.", "ref": "النهي عن الإعانة على الإثم"}]$v$::jsonb, $v$["AAOIFI المعيار الشرعي 33 (الوقف)", "قواعد السياسة الشرعية", "قرارات مجمع الفقه الإسلامي الدولي"]$v$::jsonb, 'draft', $v$مسودة أولية أُعدّت بمساعدة الذكاء الاصطناعي على نهج خبير المعايير الشرعية؛ تحتاج مراجعة الهيئة الشرعية وتوثيق الإحالات قبل الاعتماد.$v$);
